<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/includes/bootstrap.php';
require_permission('vendor_products.view');
$pdo=db();
if(is_post()){
 verify_csrf(); require_permission('vendor_products.moderate');
 try{$action=strtoupper((string)input('action'));$ids=array_values(array_filter(array_map('intval',(array)($_POST['product_ids']??[input('product_id',0)]))));$note=trim((string)input('admin_note'));if(!$ids)throw new InvalidArgumentException('Select at least one product.');if($action==='REJECT'&&$note==='')throw new InvalidArgumentException('A rejection reason is required.');if(!in_array($action,['APPROVE','REJECT','DISABLE'],true))throw new InvalidArgumentException('Invalid moderation action.');$status=['APPROVE'=>'APPROVED','REJECT'=>'REJECTED','DISABLE'=>'DISABLED'][$action];$in=implode(',',array_fill(0,count($ids),'?'));$params=array_merge([$status,$note?:null,(int)admin()['id']],$ids);$pdo->prepare("UPDATE vendor_products SET status=?,admin_note=?,moderated_by=?,moderated_at=NOW() WHERE status IN ('PENDING_REVIEW','RESUBMITTED') AND id IN ($in)")->execute($params);$count=$pdo->query('SELECT ROW_COUNT()')->fetchColumn();foreach($ids as $id)audit_log((int)admin()['id'],'PRODUCT_'.$action,'vendor_products',(string)$id,['note'=>$note]);flash('success',$count.' eligible product(s) updated.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/admin/vendors/products.php');
}
if(input('export')==='1'){require_permission('vendor_products.export');$q=trim((string)input('q'));$status=(string)input('status');$where=[];$params=[];if($q!==''){$where[]='(p.product_code LIKE ? OR p.title LIKE ? OR v.name LIKE ? OR v.shop_name LIKE ?)';array_push($params,"%$q%","%$q%","%$q%","%$q%");}if(in_array($status,['PENDING_REVIEW','APPROVED','REJECTED','DISABLED','RESUBMITTED'],true)){$where[]='p.status=?';$params[]=$status;}$sql='SELECT p.product_code,v.vendor_code,v.shop_name,p.title,p.price,p.submitted_at,p.status,p.admin_note FROM vendor_products p JOIN vendors v ON v.id=p.vendor_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.submitted_at DESC';$s=$pdo->prepare($sql);$s->execute($params);header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=vendor-products-'.date('Ymd-His').'.csv');$out=fopen('php://output','w');fputcsv($out,['Product ID','Vendor ID','Vendor / Shop','Product / Service','Price','Submission Date','Status','Admin Note']);while($r=$s->fetch(PDO::FETCH_ASSOC))fputcsv($out,csv_row([$r['product_code'],$r['vendor_code'],$r['shop_name'],$r['title'],$r['price'],$r['submitted_at'],$r['status'],$r['admin_note']]));fclose($out);exit;}
$q=trim((string)input('q'));$status=(string)input('status');$where=[];$params=[];if($q!==''){$where[]='(p.product_code LIKE ? OR p.title LIKE ? OR v.name LIKE ? OR v.shop_name LIKE ?)';array_push($params,"%$q%","%$q%","%$q%","%$q%");}if(in_array($status,['PENDING_REVIEW','APPROVED','REJECTED','DISABLED','RESUBMITTED'],true)){$where[]='p.status=?';$params[]=$status;}$condition=$where?' WHERE '.implode(' AND ',$where):'';$stats=$pdo->query("SELECT COUNT(*) total,SUM(status IN ('PENDING_REVIEW','RESUBMITTED')) pending,SUM(status='APPROVED') approved FROM vendor_products")->fetch();$sql='SELECT p.*,v.vendor_code,v.name vendor_name,v.shop_name FROM vendor_products p JOIN vendors v ON v.id=p.vendor_id'.$condition.' ORDER BY p.submitted_at DESC';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$pageTitle='Product approval & moderation';$pageSubtitle='Review vendor products and services before marketplace publication';require APP_ROOT.'/includes/header.php';
?><section class="panel"><div class="panel-head"><div><h2>Vendor product moderation</h2><p class="help">Approve eligible submissions, require correction notes, or disable published products.</p></div><?php if(can('vendor_products.export')):?><a class="btn secondary" href="?<?=http_build_query(['q'=>$q,'status'=>$status,'export'=>1])?>">Export Excel / CSV</a><?php endif?></div><div class="grid stats"><div class="card"><span class="label">Pending products</span><span class="value"><?=e((int)$stats['pending'])?></span></div><div class="card"><span class="label">Approved products</span><span class="value"><?=e((int)$stats['approved'])?></span></div><div class="card"><span class="label">Total products</span><span class="value"><?=e((int)$stats['total'])?></span></div></div><form class="filters" method="get"><input name="q" value="<?=e($q)?>" placeholder="Product ID, title or vendor"><select name="status"><option value="">All statuses</option><?php foreach(['PENDING_REVIEW','APPROVED','REJECTED','DISABLED','RESUBMITTED'] as $st):?><option value="<?=$st?>" <?=selected($status,$st)?>><?=$st?></option><?php endforeach?></select><button class="btn">Filter</button></form><form method="post" id="moderation-form"><?=csrf_field()?><div class="actions" style="margin-bottom:12px"><?php if(can('vendor_products.moderate')):?><button class="btn success" name="action" value="APPROVE">Approve selected</button><button class="btn danger" name="action" value="REJECT" onclick="return requireModerationNote()">Reject selected</button><input name="admin_note" id="bulk-note" placeholder="Required rejection/admin note"><button class="btn secondary" name="action" value="DISABLE">Disable selected</button><?php endif?></div><div class="table-wrap"><table><thead><tr><th><input type="checkbox" onclick="document.querySelectorAll('.product-check').forEach(x=>x.checked=this.checked)"></th><th>Product ID</th><th>Vendor</th><th>Product / service</th><th>Price</th><th>Submitted</th><th>Status</th><th>Reason / admin note</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><input class="product-check" type="checkbox" name="product_ids[]" value="<?=e($row['id'])?>"></td><td><strong><?=e($row['product_code'])?></strong></td><td><?=e($row['vendor_name'])?><br><small><?=e($row['shop_name'])?></small></td><td><?=e($row['title'])?></td><td><?=money($row['price'])?></td><td><?=e($row['submitted_at'])?></td><td><span class="badge <?=strtolower(e($row['status']))?>"><?=e($row['status'])?></span></td><td><?=e($row['admin_note']?:'—')?></td><td><a class="btn small secondary" href="?view=<?=e($row['id'])?>">View detail</a><?php if(can('vendor_products.moderate')&&in_array($row['status'],['PENDING_REVIEW','RESUBMITTED'],true)):?><button class="btn small success" name="action" value="APPROVE">Approve</button><?php endif?></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="empty">No vendor products match the selected filters.</div><?php endif?></div></form></section><?php if(($view=(int)input('view'))>0):$v=$pdo->prepare('SELECT p.*,v.vendor_code,v.name vendor_name,v.shop_name,v.email,v.mobile FROM vendor_products p JOIN vendors v ON v.id=p.vendor_id WHERE p.id=?');$v->execute([$view]);if($detail=$v->fetch()):?><section class="panel"><div class="panel-head"><h2>Product detail · <?=e($detail['product_code'])?></h2><a class="btn secondary" href="<?=e(app_url('/admin/vendors/products.php'))?>">Close</a></div><div class="grid detail-grid"><div><div class="kv"><span>Vendor</span><strong><?=e($detail['vendor_name'].' · '.$detail['shop_name'])?></strong></div><div class="kv"><span>Contact</span><strong><?=e($detail['email']?:'—')?> · <?=e($detail['mobile']?:'—')?></strong></div><div class="kv"><span>Title</span><strong><?=e($detail['title'])?></strong></div><div class="kv"><span>Description</span><strong><?=e($detail['description']?:'—')?></strong></div></div><div><div class="kv"><span>Price</span><strong><?=money($detail['price'])?></strong></div><div class="kv"><span>Status</span><strong><?=e($detail['status'])?></strong></div><div class="kv"><span>Admin note</span><strong><?=e($detail['admin_note']?:'—')?></strong></div><div class="kv"><span>Submitted</span><strong><?=e($detail['submitted_at'])?></strong></div></div></div></section><?php endif;endif;require APP_ROOT.'/includes/footer.php';?><script>function requireModerationNote(){if(!document.getElementById('bulk-note').value.trim()){alert('Enter a rejection reason.');return false}return true}</script>
